sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Initiate GlideAjax with the Script Include Name

    var gaVdi = new GlideAjax('VDIUserLookupUtil');
    gaVdi.addParam('sysparm_name', 'getExistingVDI');
    gaVdi.addParam('sysparm_user_id', newValue); // Passes the selected user Sys ID
    gaVdi.getXMLAnswer(vdiCallback);

}

// Callback function to process the server response

function vdiCallback(answer) {
    if (!answer) {
        return;
    }
    try {
        var response = JSON.parse(answer);

        if (response.found) {
            // Example: Alerting the user or populating fields
            g_form.addInfoMessage('Existing VDI found: ' + response.name);
			g_form.setValue('u_configuration_item',response.sys_id, response.name);
			g_form.setValue('u_request_type', 'upgrade');
        } else {
            g_form.addInfoMessage('No active VDI found for this user.');
        }
    } catch (e) {
        jslog('Error parsing VDI lookup JSON response: ' + e);
    }
}
